import { useEffect, useRef, useState } from "react";
import { toast, Toaster } from "sonner";
import { Activity, ArrowLeft, ArrowRight, BookOpen, ChevronDown, CircleHelp, Database, Eye, FileJson, FlaskConical, KeyRound, Layers3, Plus, RotateCcw, Search, Settings2, Sun, Moon, Trash2, X } from "lucide-react";
import { Badge } from "@/components/ui/badge";
import { Button } from "@/components/ui/button";
import { Card, CardContent, CardHeader, CardTitle } from "@/components/ui/card";
import { Checkbox } from "@/components/ui/checkbox";
import { Dialog, DialogContent, DialogDescription, DialogFooter, DialogHeader, DialogTitle } from "@/components/ui/dialog";
import { Input } from "@/components/ui/input";
import { Popover, PopoverContent, PopoverTrigger } from "@/components/ui/popover";
import { Select, SelectContent, SelectItem, SelectTrigger, SelectValue } from "@/components/ui/select";
import { Sheet, SheetContent, SheetDescription, SheetFooter, SheetHeader, SheetTitle } from "@/components/ui/sheet";
import { Sidebar, SidebarContent, SidebarFooter, SidebarGroup, SidebarGroupContent, SidebarGroupLabel, SidebarHeader, SidebarMenu, SidebarMenuButton, SidebarMenuItem, SidebarProvider, SidebarTrigger, useSidebar } from "@/components/ui/sidebar";
import { Switch } from "@/components/ui/switch";
import { Table, TableBody, TableCell, TableHead, TableHeader, TableRow } from "@/components/ui/table";
import { Textarea } from "@/components/ui/textarea";
import { Tooltip, TooltipContent, TooltipProvider, TooltipTrigger } from "@/components/ui/tooltip";
import { copy, delta, exposed, fixture, discoveryModels, keyImpact, kindFor, members, modelImpact, origin, same, toggleModel, type Access, type Capability, type Demo, type Group, type Key, type Model, type Policy } from "./demo";
import ModelBrowser from "./ModelBrowser";
import { GroupTree } from "./GroupTree";
import { displayProvider } from "./BrandIcon";
import { ViewControls, defaultViewOptions, type ViewOptions } from "./ViewOptions";
import Laboratory from "./Laboratory";

type Page = "models" | "groups" | "keys" | "qualification" | "settings";
type Confirm = { title: string; text: string; action: () => void; confirmLabel?: string; cancelLabel?: string } | null;
const nav: { id: Page; label: string; icon: typeof Database }[] = [
  { id: "models", label: "Model Catalog", icon: Database },
  { id: "groups", label: "Groups", icon: Layers3 },
  { id: "keys", label: "Virtual Keys", icon: KeyRound },
  { id: "qualification", label: "Laboratory", icon: FlaskConical },
  { id: "settings", label: "Settings", icon: Settings2 },
];
const formats: Policy["naming"][] = ["model", "provider/model", "both"];
function UiSelect({ label, value, options, onChange, className = "" }: { label: string; value: string; options: string[]; onChange: (value: string) => void; className?: string }) {
  return <Select value={value} onValueChange={onChange}><SelectTrigger aria-label={label} className={className}><SelectValue /></SelectTrigger><SelectContent>{options.map(option => <SelectItem key={option} value={option}>{option}</SelectItem>)}</SelectContent></Select>;
}

const tasks = ["Chat", "Code", "Reasoning", "Vision", "Image generation", "Embeddings", "Audio transcription", "Audio generation", "Video generation"];
const modalities = ["Text", "Image", "Audio", "Video", "Vector"];
function TaxonomyChoices({ label, options, selected, onChange }: { label: string; options: string[]; selected: string[]; onChange: (next: string[]) => void }) {
  return <fieldset><legend className="mb-2 text-sm font-medium">{label}</legend><div className="flex flex-wrap gap-2">{options.map(option => <label key={option} className="flex cursor-pointer items-center gap-2 rounded-sm border px-2 py-1.5 text-xs hover:bg-muted/40"><Checkbox checked={selected.includes(option)} onCheckedChange={checked => onChange(checked ? [...selected, option] : selected.filter(value => value !== option))} />{option}</label>)}</div></fieldset>;
}

function ProviderPicker({ value, onChange }: { value: string; onChange: (value: string) => void }) {
  const [open, setOpen] = useState(false);
  const [query, setQuery] = useState("");
  const providers = ["openai", "azure", "anthropic", "bedrock", "google", "moonshot", "openrouter"];
  const matches = providers.filter(id => `${id} ${displayProvider(id)}`.toLowerCase().includes(query.toLowerCase()));
  return <Popover open={open} onOpenChange={setOpen}><PopoverTrigger asChild><Button variant="outline" className="w-full justify-between" aria-label="Serving provider">{providers.includes(value) ? displayProvider(value) : value || "Choose provider"}<ChevronDown className="size-4" /></Button></PopoverTrigger><PopoverContent align="start" className="w-64"><Input autoFocus aria-label="Search serving providers" placeholder="Search providers…" value={query} onChange={e => setQuery(e.target.value)} /><div className="mt-2 max-h-48 overflow-auto">{matches.map(id => <Button key={id} variant="ghost" className="w-full justify-start" onClick={() => { onChange(id); setOpen(false); setQuery(""); }}>{displayProvider(id)}</Button>)}{!matches.length && <p className="p-2 text-xs text-muted-foreground">No providers found.</p>}</div><Button variant="ghost" className="mt-2 w-full justify-start" onClick={() => { onChange(""); setOpen(false); setQuery(""); }}>Advanced: custom provider</Button></PopoverContent></Popover>;
}

function route(): { page: Page; id?: string } {
  const [page, id] = location.hash.slice(2).split("/");
  return { page: nav.some(n => n.id === page) ? page as Page : "models", id };
}

function MobileSidebarLabel() {
  const { isMobile } = useSidebar();
  return isMobile ? <><SheetTitle className="sr-only">Navigation</SheetTitle><SheetDescription className="sr-only">Registry pages and settings</SheetDescription></> : null;
}

function CloseMobileSidebarOnRoute({ routeKey }: { routeKey: string }) {
  const { setOpenMobile } = useSidebar();
  useEffect(() => setOpenMobile(false), [routeKey, setOpenMobile]);
  return null;
}

export function App() {
  const [data, setData] = useState<Demo>(() => copy(fixture));
  const [locationState, setLocationState] = useState(route);
  const [search, setSearch] = useState("");
  const [modelDraft, setModelDraft] = useState<Model | null>(null);
  const [creatingModel, setCreatingModel] = useState(false);
  const [modelError, setModelError] = useState("");
  const [groupDraft, setGroupDraft] = useState<Group | null>(null);
  const [groupEditorView, setGroupEditorView] = useState<"cards" | "tree">("cards");
  const [keyForm, setKeyForm] = useState<{ name: string; client: string } | null>(null);
  const [renameForm, setRenameForm] = useState<{ id: string; name: string } | null>(null);
  const [discoveryOpen, setDiscoveryOpen] = useState(false);
  const [preferences, setPreferences] = useState<ViewOptions>(() => { try { return { ...defaultViewOptions, ...JSON.parse(localStorage.getItem("registry-prototype-view") || "{}") }; } catch { return defaultViewOptions; } });
  const [listOverrides, setListOverrides] = useState<Record<string, Partial<ViewOptions>>>({});
  const [selectionView, setSelectionView] = useState<ViewOptions>(defaultViewOptions);
  useEffect(() => { localStorage.setItem("registry-prototype-view", JSON.stringify(preferences)); }, [preferences]);
  const [dark, setDark] = useState(() => document.documentElement.classList.contains("dark"));
  useEffect(() => { document.documentElement.classList.toggle("dark", dark); document.documentElement.style.colorScheme = dark ? "dark" : "light"; }, [dark]);
  const [confirm, setConfirm] = useState<Confirm>(null);
  const [draft, setDraft] = useState<Policy | null>(null);
  const [failRead, setFailRead] = useState(false);
  const [tour, setTour] = useState<number | null>(null);
  const [tourRect, setTourRect] = useState<DOMRect | null>(null);
  const [showJson, setShowJson] = useState(false);

  useEffect(() => { const onHash = () => { setLocationState(route()); setSearch(""); }; addEventListener("hashchange", onHash); return () => removeEventListener("hashchange", onHash); }, []);
  const navigate = (page: Page, id?: string) => { location.hash = `/${page}${id ? `/${id}` : ""}`; setLocationState({ page, id }); setSearch(""); };
  const go = (page: Page, id?: string) => {
    if (locationState.page === "keys" && locationState.id && draft && !same(data.keys.find(k => k.id === locationState.id)?.policy, draft) && (page !== "keys" || id !== locationState.id)) {
      setConfirm({ title: "Discard key draft?", text: "Unpublished key selections will be lost.", confirmLabel: "Discard changes", cancelLabel: "Keep editing", action: () => navigate(page, id) });
      return;
    }
    navigate(page, id);
  };
  const { page, id: pageId } = locationState;
  const contentRef = useRef<HTMLDivElement>(null);
  useEffect(() => { contentRef.current?.scrollTo(0, 0); }, [page, pageId]);
  const key = data.keys.find(k => k.id === pageId);
  useEffect(() => { setDraft(key ? copy(key.policy) : null); setShowJson(false); }, [key?.id]);
  const activePolicy = draft || key?.policy;
  const predicted = activePolicy ? exposed(activePolicy, data.groups, data.models) : [];
  const observed = key?.observed || [];
  const diff = delta(observed, predicted);
  const isDirty = Boolean(key && draft && !same(key.policy, draft));
  const filteredGroups = data.groups.filter(g => `${g.name} ${g.description}`.toLowerCase().includes(search.toLowerCase()));
  const filteredKeys = data.keys.filter(k => `${k.name} ${k.client}`.toLowerCase().includes(search.toLowerCase()));

  const newModel = (): Model => ({ id: "", name: "", creator: "", family: "", inputModalities: ["Text"], outputModalities: ["Text"], tasks: ["Chat"], kind: "Chat", summary: "", context: "Unknown", capabilities: { Chat: "Unknown", Streaming: "Unknown", Tools: "Unknown", Vision: "Unknown" }, accesses: [{ provider: "", id: "", route: "Direct provider", status: "Unknown" }] });
  const updateModel = () => {
    if (!modelDraft) return;
    if (!/^[a-z0-9][a-z0-9._-]*$/.test(modelDraft.id) || !modelDraft.name.trim() || !modelDraft.creator.trim() || !modelDraft.family.trim() || !modelDraft.tasks.length || !modelDraft.inputModalities.length || !modelDraft.outputModalities.length || !modelDraft.accesses.length || !modelDraft.accesses.every(a => a.provider.trim() && a.id.trim())) { setModelError("Enter an ID, name, creator, series, usage, input/output modalities, and a provider access."); return; }
    const existing = !creatingModel;
    if (creatingModel && data.models.some(m => m.id === modelDraft.id)) { setModelError("That model ID already exists."); return; }
    const allAccessIds = data.models.filter(m => m.id !== modelDraft.id).flatMap(m => m.accesses.map(a => a.id));
    if (modelDraft.accesses.some(a => allAccessIds.includes(a.id)) || new Set(modelDraft.accesses.map(a => a.id)).size !== modelDraft.accesses.length) { setModelError("Provider access IDs must be unique."); return; }
    const saved = { ...modelDraft, kind: kindFor(modelDraft) };
    setData(old => ({ ...old, models: existing ? old.models.map(m => m.id === saved.id ? copy(saved) : m) : [...old.models, copy(saved)] }));
    setModelDraft(null); setModelError(""); toast.success(existing ? "Model updated in demo." : "Model created in demo.");
  };
  const deleteModel = (model: Model) => {
    setModelDraft(null);
    const used = data.keys.filter(k => members(k.policy, data.groups).includes(model.id)).length;
    setConfirm({ title: `Delete ${model.name}?`, text: `This removes the model from its groups and key selections. ${used} key catalog${used === 1 ? "" : "s"} will change.`, action: () => {
      setData(old => {
        const models = old.models.filter(m => m.id !== model.id);
        const groups = old.groups.map(g => ({ ...g, members: g.members.filter(id => id !== model.id) }));
        const keys = old.keys.map(k => {
          const policy = { ...k.policy, added: k.policy.added.filter(id => id !== model.id), excluded: k.policy.excluded.filter(id => id !== model.id) };
          return { ...k, policy, observed: failRead ? k.observed : exposed(policy, groups, models), readError: failRead };
        });
        return { ...old, models, groups, keys };
      });
      toast.success("Model deleted in demo.");
    } });
  };
  const publishGroup = () => {
    if (!groupDraft?.name.trim()) { toast.error("Enter a group name."); return; }
    const exists = data.groups.some(g => g.id !== groupDraft.id && g.name.toLowerCase() === groupDraft.name.trim().toLowerCase());
    if (exists) { toast.error("A group with this name already exists."); return; }
    const nextGroup = { ...groupDraft, name: groupDraft.name.trim() };
    const nextGroups = data.groups.some(g => g.id === groupDraft.id) ? data.groups.map(g => g.id === groupDraft.id ? nextGroup : g) : [...data.groups, nextGroup];
    const impacted = keyImpact(data.keys, data.groups, nextGroups, data.models);
    setData(old => ({ ...old, groups: nextGroups, keys: old.keys.map(k => impacted.some(x => x.key.id === k.id) ? { ...k, observed: failRead ? k.observed : exposed(k.policy, nextGroups, old.models), readError: failRead, revision: k.revision + 1 } : k) }));
    setGroupDraft(null);
    toast[failRead ? "warning" : "success"](failRead ? "Group published; simulated readback failed." : `Group published; ${impacted.length} key catalog${impacted.length === 1 ? "" : "s"} updated.`);
  };
  const saveKey = () => {
    if (!keyForm?.name.trim()) { toast.error("Enter a key name."); return; }
    if (data.keys.some(k => k.name.toLowerCase() === keyForm.name.trim().toLowerCase())) { toast.error("A key with this name already exists."); return; }
    const id = crypto.randomUUID();
    const newKey: Key = { id, name: keyForm.name.trim(), client: keyForm.client.trim() || "Unassigned", active: true, policy: { groups: [], added: [], excluded: [], naming: "model" }, observed: [], readError: false, revision: 1 };
    setData(old => ({ ...old, keys: [...old.keys, newKey] })); setKeyForm(null); go("keys", id); toast.success("Virtual key created in the demo. No secret was generated.");
  };
  const publishKey = () => {
    if (!key || !draft) return;
    const expected = exposed(draft, data.groups, data.models);
    setData(old => ({ ...old, keys: old.keys.map(k => k.id === key.id ? { ...k, policy: copy(draft), observed: failRead ? k.observed : expected, readError: failRead, revision: k.revision + 1 } : k) }));
    toast[failRead ? "warning" : "success"](failRead ? "Published in the demo; readback is unavailable." : "Published and read back in the demo.");
  };
  const reread = () => {
    if (!key) return;
    setData(old => ({ ...old, keys: old.keys.map(k => k.id === key.id ? { ...k, observed: failRead ? k.observed : exposed(k.policy, old.groups, old.models), readError: failRead } : k) }));
    toast[failRead ? "error" : "success"](failRead ? "Simulated readback unavailable. Last result retained." : "Simulated /v1/models readback updated.");
  };
  const reset = () => { setData(copy(fixture)); setDraft(null); setGroupDraft(null); setModelDraft(null); setConfirm(null); setFailRead(false); setSearch(""); navigate("models"); toast.success("Demo reset."); };
  const downloadJson = () => {
    if (!key) return;
    const payload = { object: "list", data: observed.map(id => ({ id, object: "model" })) };
    const link = document.createElement("a"); link.href = URL.createObjectURL(new Blob([JSON.stringify(payload, null, 2)], { type: "application/json" })); link.download = `${key.name.toLowerCase().replace(/\s+/g, "-")}-simulated-models.json`; link.click(); URL.revokeObjectURL(link.href);
  };

  const tourSteps = [
    { page: "models" as Page, selector: "[data-tour='first-model']", title: "One model, several accesses", detail: "Open a card to compare providers and evidence." },
    { page: "models" as Page, selector: "[data-tour='filters']", title: "Find the right model", detail: "Search or filter by provider and type." },
    { page: "groups" as Page, selector: "[data-tour='groups']", title: "Shared groups", detail: "Edit once and preview which keys will change." },
    { page: "keys" as Page, selector: "[data-tour='keys']", title: "Virtual keys", detail: "Open Hermes to compose its catalog." },
    { page: "keys" as Page, id: "hermes", selector: "[data-tour='composer']", title: "Local choices", detail: "Combine groups, single models, and key-only exclusions." },
    { page: "keys" as Page, id: "hermes", selector: "[data-tour='preview']", title: "Preview and readback", detail: "The draft and the last simulated /v1/models response stay separate." },
  ];
  useEffect(() => {
    if (tour === null) return;
    const step = tourSteps[tour];
    if (page !== step.page || pageId !== step.id) { go(step.page, step.id); return; }
    const update = () => setTourRect(document.querySelector(step.selector)?.getBoundingClientRect() || null);
    const timer = setTimeout(() => { document.querySelector(step.selector)?.scrollIntoView({ block: "center" }); update(); }, 80); addEventListener("resize", update); addEventListener("scroll", update, true);
    return () => { clearTimeout(timer); removeEventListener("resize", update); removeEventListener("scroll", update, true); };
  }, [tour, page, pageId, data]);

  const viewFor = (scope: string) => ({ ...preferences, ...listOverrides[scope] });
  const setView = (scope: string, value: ViewOptions) => setListOverrides(old => { const current = { ...preferences, ...old[scope] }; const changed = (Object.keys(value) as (keyof ViewOptions)[]).find(field => value[field] !== current[field]); return changed ? { ...old, [scope]: { ...old[scope], [changed]: value[changed] } } : old; });
  const resetView = (scope: string) => setListOverrides(old => { const next = { ...old }; delete next[scope]; return next; });
  const title = page === "models" ? "Model Catalog" : page === "groups" ? "Groups" : page === "qualification" ? "Laboratory" : page === "settings" ? "Settings" : key ? key.name : "Virtual Keys";
  return <TooltipProvider delayDuration={0}><SidebarProvider><CloseMobileSidebarOnRoute routeKey={`${page}/${pageId || ""}`} /><Sidebar inert={tour !== null} collapsible="icon" className="border-none bg-transparent"><SidebarHeader className="px-4 pt-5 pb-3"><MobileSidebarLabel /><div className="flex items-center justify-between gap-2"><a href="#/models" onClick={e => { e.preventDefault(); go("models"); }} className="min-w-0"><img src="/bifrost-logo.webp" alt="Bifrost" className="h-[22px] max-w-[145px] object-contain object-left dark:hidden" /><img src="/bifrost-logo-dark.webp" alt="Bifrost" className="hidden h-[22px] max-w-[145px] object-contain object-left dark:block" /></a><SidebarTrigger className="size-7" /></div></SidebarHeader><SidebarContent><SidebarGroup><SidebarGroupLabel>WORKSPACE</SidebarGroupLabel><SidebarGroupContent><SidebarMenu>{nav.map(item => { const Icon = item.icon; return <SidebarMenuItem key={item.id}><SidebarMenuButton asChild isActive={page === item.id} tooltip={item.label}><a href={`#/${item.id}`} onClick={e => { e.preventDefault(); go(item.id); }} className={page === item.id ? "border border-primary/20 text-primary" : "border border-transparent"}><Icon className="size-4" /><span>{item.label}</span></a></SidebarMenuButton></SidebarMenuItem>; })}</SidebarMenu></SidebarGroupContent></SidebarGroup></SidebarContent><SidebarFooter className="p-4"><span className="text-xs text-muted-foreground group-data-[collapsible=icon]:hidden">Registry prototype</span></SidebarFooter></Sidebar>
    <div inert={tour !== null} className="flex h-dvh w-full min-w-0 flex-col"><header className="flex h-13 w-full shrink-0 items-center gap-2 px-3 pt-1 md:pr-3 md:pl-0"><SidebarTrigger className="md:hidden" /><h1 className="min-w-0 flex-1 truncate text-base font-semibold">{key && page === "keys" ? <><button onClick={() => go("keys")} className="text-muted-foreground hover:text-foreground">Virtual Keys</button><span className="mx-2 text-muted-foreground/50">/</span>{title}</> : title}</h1><Tooltip><TooltipTrigger asChild><CircleHelp className="hidden size-4 cursor-help text-muted-foreground sm:block" /></TooltipTrigger><TooltipContent>{page === "models" ? "Explore models and provider accesses" : page === "groups" ? "Shared sets of models for keys" : page === "keys" ? "Compose and publish key catalogs" : page === "settings" ? "View preferences for this prototype" : "Illustrative harness coverage and campaigns"}</TooltipContent></Tooltip><div className="ml-auto flex items-center gap-2"><Badge variant="warning" className="text-[10px]"><span className="sm:hidden">DEMO</span><span className="hidden sm:inline">SIMULATION</span></Badge><Popover><PopoverTrigger asChild><Button variant="ghost" size="icon" aria-label="Demo settings" title="Demo settings"><Settings2 className="size-4" /></Button></PopoverTrigger><PopoverContent align="end" className="w-64"><h3 className="mb-2 text-sm font-medium">Demo settings</h3><label className="flex items-center justify-between gap-3 text-xs"><span>Simulate readback failures</span><Switch checked={failRead} onCheckedChange={setFailRead} /></label><p className="mt-2 text-xs text-muted-foreground">All actions use browser memory only.</p><Button variant="outline" size="sm" className="mt-3 w-full" onClick={reset}><RotateCcw className="size-3.5" />Reset demo</Button></PopoverContent></Popover><Button variant="ghost" size="icon" aria-label={dark ? "Use light theme" : "Use dark theme"} title={dark ? "Use light theme" : "Use dark theme"} onClick={() => setDark(!dark)}>{dark ? <Sun className="size-4" /> : <Moon className="size-4" />}</Button><Button variant="ghost" size="sm" aria-label="Quick tour" onClick={() => setTour(0)}><BookOpen className="size-4" /><span className="hidden sm:inline">Quick tour</span></Button><div className="hidden items-center gap-2 rounded-full border bg-card px-2 py-1 md:flex"><span className="flex size-5 items-center justify-center rounded-full bg-muted text-[10px] font-semibold">S</span><span className="text-xs font-medium">Sofian</span><ChevronDown className="size-3 text-muted-foreground" /></div></div></header>
      <div ref={contentRef} className="custom-scrollbar content-container mx-0 min-h-0 min-w-0 flex-1 overflow-auto border border-gray-200 bg-white md:mr-3 md:mb-3 md:rounded-md md:px-10 dark:border-zinc-800 dark:bg-card"><main className="mx-auto max-w-[1440px] px-4 py-5 md:px-0 md:py-7">
        {page === "models" && <><div className="mb-5 flex flex-wrap items-end justify-between gap-3"><div><h2 className="text-xl font-semibold">Models</h2><p className="mt-1 text-sm text-muted-foreground">Browse models, their creators and serving provider accesses.</p></div><div className="flex items-center gap-2"><Badge variant="secondary">{data.models.length} models · {data.models.reduce((n, m) => n + m.accesses.length, 0)} accesses</Badge><Button onClick={() => setDiscoveryOpen(true)}><Plus className="size-4" />Add model</Button></div></div><ModelBrowser models={data.models} preferences={preferences} onOpen={model => { setCreatingModel(false); setModelError(""); setModelDraft(copy(model)); }} tourFirst /></>}
        {page === "groups" && <><div className="mb-5 flex flex-wrap items-end justify-between gap-3"><div><h2 className="text-xl font-semibold">Groups</h2><p className="mt-1 text-sm text-muted-foreground">Reusable model selections shared by virtual keys.</p></div><Button data-tour="groups" onClick={() => setGroupDraft({ id: crypto.randomUUID(), name: "", description: "", members: [] })}><Plus className="size-4" />Create group</Button></div><div className="mb-5 flex flex-wrap items-center justify-between gap-3"><div className="relative min-w-[220px] max-w-sm flex-1"><Search className="absolute top-2.5 left-3 size-4 text-muted-foreground" /><Input aria-label="Search groups" placeholder="Search groups..." className="pl-9" value={search} onChange={e => setSearch(e.target.value)} /></div><ViewControls value={{...preferences, ...listOverrides["groups"]}} onChange={next => setView("groups", next)} onReset={() => resetView("groups")} scope="Groups" fields={["description", "metadata", "providers"]} /></div>{viewFor("groups").layout === "grid" ? <div className={`grid gap-3 ${viewFor("groups").size === "small" ? "sm:grid-cols-2 xl:grid-cols-4" : viewFor("groups").size === "large" ? "lg:grid-cols-2" : "sm:grid-cols-2 xl:grid-cols-3"}`}>{filteredGroups.map((g, index) => <Card key={g.id} data-tour={index === 0 ? "groups" : undefined} className="gap-4 py-5"><CardHeader className="px-4 sm:px-6"><CardTitle className="flex items-center gap-2 text-sm"><Layers3 className="size-4" />{g.name}</CardTitle></CardHeader><CardContent className="space-y-3 px-4 sm:px-6">{viewFor("groups").description && <p className="text-xs text-muted-foreground">{g.description || "No description"}</p>}{viewFor("groups").metadata && <p className="text-xs">{g.members.length} selected models</p>}{viewFor("groups").providers && <p className="text-xs text-muted-foreground">Used by {data.keys.filter(k => k.policy.groups.includes(g.id)).map(k => k.name).join(", ") || "no keys"}</p>}<Button variant="outline" size="sm" className="mt-2 w-fit" onClick={() => setGroupDraft(copy(g))}>Edit group <ArrowRight className="size-3.5" /></Button></CardContent></Card>)}</div> : <div className="overflow-hidden rounded-sm border"><Table className="[&_td]:py-3 [&_td]:whitespace-normal [&_th]:h-12"><TableHeader><TableRow><TableHead>Group</TableHead><TableHead>Models</TableHead><TableHead>Used by</TableHead><TableHead className="text-right">Action</TableHead></TableRow></TableHeader><TableBody>{filteredGroups.map(g => <TableRow key={g.id} className="cursor-pointer" onClick={() => setGroupDraft(copy(g))}><TableCell><div className="font-medium">{g.name}</div><div className="mt-1 text-xs text-muted-foreground">{g.description || "No description"}</div></TableCell><TableCell>{g.members.length} models</TableCell><TableCell className="space-x-1">{data.keys.filter(k => k.policy.groups.includes(g.id)).map(k => <Badge key={k.id} variant="secondary" className="font-mono">{k.name}</Badge>)}{!data.keys.some(k => k.policy.groups.includes(g.id)) && <span className="text-muted-foreground">—</span>}</TableCell><TableCell className="text-right"><Button size="sm" variant="ghost" onClick={e => { e.stopPropagation(); setGroupDraft(copy(g)); }}>Edit <ArrowRight className="size-3.5" /></Button></TableCell></TableRow>)}</TableBody></Table></div>}{!filteredGroups.length && <Empty icon={Layers3} title="No matching groups" detail={data.groups.length ? "Try another search." : "Create a group to reuse its models across keys."} action={<Button onClick={() => { setSearch(""); setGroupDraft({ id: crypto.randomUUID(), name: "", description: "", members: [] }); }}>Create group</Button>} />}</>}
        {page === "keys" && !key && <><div className="mb-5 flex flex-wrap items-end justify-between gap-3"><div><h2 className="text-xl font-semibold">Virtual Keys</h2><p className="mt-1 text-sm text-muted-foreground">Create a key, compose its catalog, and inspect simulated readback.</p></div><Button onClick={() => setKeyForm({ name: "", client: "" })}><Plus className="size-4" />Create key</Button></div><div className="mb-5 flex flex-wrap items-center justify-between gap-3"><div className="relative min-w-[220px] max-w-sm flex-1"><Search className="absolute top-2.5 left-3 size-4 text-muted-foreground" /><Input aria-label="Search keys" placeholder="Search keys..." className="pl-9" value={search} onChange={e => setSearch(e.target.value)} /></div><ViewControls value={{...preferences, ...listOverrides["keys"]}} onChange={next => setView("keys", next)} onReset={() => resetView("keys")} scope="Keys" fields={["description", "metadata", "providers"]} /></div>{viewFor("keys").layout === "grid" ? <div className={`grid gap-3 ${viewFor("keys").size === "small" ? "sm:grid-cols-2 xl:grid-cols-4" : viewFor("keys").size === "large" ? "lg:grid-cols-2" : "sm:grid-cols-2 xl:grid-cols-3"}`}>{filteredKeys.map((k, index) => <Card key={k.id} data-tour={index === 0 ? "keys" : undefined} className="gap-4 py-5"><CardHeader className="px-4 sm:px-6"><CardTitle className="flex items-center gap-2 text-sm"><KeyRound className="size-4" />{k.name}</CardTitle></CardHeader><CardContent className="space-y-3 px-4 sm:px-6">{viewFor("keys").description && <p className="text-xs text-muted-foreground">Client: {k.client}</p>}{viewFor("keys").metadata && <p className="text-xs">{members(k.policy, data.groups).length} visible models</p>}{viewFor("keys").providers && <p className="text-xs text-muted-foreground">Groups: {k.policy.groups.map(id => data.groups.find(g => g.id === id)?.name).filter(Boolean).join(", ") || "None"}</p>}<div className="flex flex-wrap items-center gap-2 pt-2"><Badge variant={k.active ? "success" : "secondary"}>{k.active ? "Active" : "Disabled"}</Badge><Button variant="outline" size="sm" onClick={() => go("keys", k.id)}>Open key <ArrowRight className="size-3.5" /></Button></div></CardContent></Card>)}</div> : <div className="overflow-hidden rounded-sm border"><Table className="[&_td]:py-3 [&_td]:whitespace-normal [&_th]:h-12"><TableHeader><TableRow><TableHead>Key</TableHead><TableHead>Client</TableHead><TableHead>Groups</TableHead><TableHead>Models</TableHead><TableHead>Status</TableHead><TableHead className="text-right">Action</TableHead></TableRow></TableHeader><TableBody>{filteredKeys.map((k, index) => <TableRow key={k.id} data-tour={index === 0 ? "keys" : undefined} className="cursor-pointer" onClick={() => go("keys", k.id)}><TableCell className="font-medium">{k.name}</TableCell><TableCell className="text-muted-foreground">{k.client}</TableCell><TableCell>{k.policy.groups.map(id => data.groups.find(g => g.id === id)?.name).filter(Boolean).join(", ") || "—"}</TableCell><TableCell>{members(k.policy, data.groups).length}</TableCell><TableCell><Badge variant={k.active ? "success" : "secondary"}>{k.active ? "Active" : "Disabled"}</Badge></TableCell><TableCell className="text-right"><Button variant="ghost" size="sm" onClick={e => { e.stopPropagation(); go("keys", k.id); }}>Open <ArrowRight className="size-3.5" /></Button></TableCell></TableRow>)}</TableBody></Table></div>}{!filteredKeys.length && <Empty icon={KeyRound} title="No matching keys" detail={data.keys.length ? "Try another search." : "Create a virtual key to start composing a catalog."} action={<Button onClick={() => { setSearch(""); setKeyForm({ name: "", client: "" }); }}>Create key</Button>} />}</>}
        {page === "keys" && key && activePolicy && <><div className="mb-6 flex flex-wrap items-start justify-between gap-4"><div><Button variant="ghost" size="sm" className="mb-2 -ml-2" onClick={() => go("keys")}><ArrowLeft className="size-4" />All keys</Button><div className="flex items-center gap-2"><h2 className="text-xl font-semibold">{key.name}</h2><Badge variant={key.active ? "success" : "secondary"}>{key.active ? "Active" : "Disabled"}</Badge></div><p className="mt-1 text-sm text-muted-foreground">{key.client} · Revision {key.revision} · Credential simulated, no secret generated</p></div><div className="flex flex-wrap items-center gap-2"><Button variant="outline" onClick={() => setRenameForm({ id: key.id, name: key.name })}>Rename</Button><Button variant="outline" onClick={() => setData(old => ({ ...old, keys: old.keys.map(x => x.id === key.id ? { ...x, active: !x.active } : x) }))}>{key.active ? "Disable" : "Enable"}</Button><Button variant="ghost" size="icon" aria-label="Delete key" onClick={() => setConfirm({ title: `Delete ${key.name}?`, text: "This removes the simulated key and its local catalog configuration.", action: () => { setData(old => ({ ...old, keys: old.keys.filter(x => x.id !== key.id) })); go("keys"); toast.success("Key deleted in demo."); } })}><Trash2 className="size-4 text-destructive" /></Button></div></div>
          <div className="grid min-w-0 gap-6 xl:grid-cols-[minmax(0,1.4fr)_minmax(300px,.8fr)]"><div className="min-w-0 space-y-5"><Card className="gap-5 py-5 sm:py-6"><CardHeader className="px-4 sm:px-6"><CardTitle className="text-base">Compose catalog</CardTitle><p className="text-xs text-muted-foreground">Changes apply only to {key.name}. Shared groups are managed separately.</p></CardHeader><CardContent className="space-y-6 px-4 sm:px-6"><section data-tour="composer"><div className="mb-3 flex flex-wrap items-center justify-between gap-2"><h3 className="text-sm font-medium">Shared groups</h3><Button variant="link" size="sm" onClick={() => go("groups")}>Manage groups <ArrowRight className="size-3.5" /></Button></div><div className="grid gap-3 sm:grid-cols-2">{data.groups.map(g => <label key={g.id} className="flex cursor-pointer items-center gap-3 rounded-sm border p-3 hover:bg-muted/40"><Checkbox checked={activePolicy.groups.includes(g.id)} onCheckedChange={checked => setDraft(old => old ? { ...old, groups: checked ? [...old.groups, g.id] : old.groups.filter(x => x !== g.id) } : old)} /><span className="flex-1"><span className="block text-sm font-medium">{g.name}</span><span className="text-xs text-muted-foreground">{g.members.length} models</span></span></label>)}</div>{!data.groups.length && <p className="text-sm text-muted-foreground">No groups yet. Add individual models below or create a group.</p>}</section><section className="border-t pt-6"><h3 className="mb-2 text-sm font-medium">Models and local exceptions</h3><p className="mb-3 text-xs text-muted-foreground">An exclusion here does not change a shared group or another key.</p><p className="mb-2 text-xs text-muted-foreground">{members(activePolicy, data.groups).length} selected · {activePolicy.excluded.length} local exclusions. Selected models remain selected when filters hide them.</p><ModelBrowser models={data.models} selected={members(activePolicy, data.groups)} onToggle={id => setDraft(old => old ? toggleModel(old, id, data.groups) : old)} onSetSelected={ids => setDraft(old => old ? data.models.reduce((policy, model) => members(policy, data.groups).includes(model.id) === ids.includes(model.id) ? policy : toggleModel(policy, model.id, data.groups), old) : old)} preferences={preferences} compact label="Key models" /><div className="mt-2 flex flex-wrap gap-1">{activePolicy.excluded.map(id => <Badge key={id} variant="outline">Excluded locally: {data.models.find(m => m.id === id)?.name || id}</Badge>)}</div></section><section className="border-t pt-6"><h3 className="mb-2 text-sm font-medium">Visible model names</h3><div className="flex flex-wrap gap-2">{formats.map(format => <Button key={format} variant={activePolicy.naming === format ? "default" : "outline"} size="sm" onClick={() => setDraft(old => old ? { ...old, naming: format } : old)}>{format}</Button>)}</div><p className="mt-2 text-xs text-muted-foreground">Short names use the explicitly configured Bifrost route. Multiple accesses do not imply load balancing.</p></section></CardContent></Card><div className="flex flex-wrap items-center gap-3"><Button disabled={!isDirty} onClick={publishKey}>Publish changes</Button><Button variant="outline" disabled={!isDirty} onClick={() => { setDraft(copy(key.policy)); toast.success("Draft discarded."); }}>Discard draft</Button><span className="basis-full text-xs text-muted-foreground sm:basis-auto">{isDirty ? "Unpublished changes" : "Draft matches published policy"}</span></div></div>
          <div className="min-w-0 space-y-5"><Card data-tour="preview" className="gap-5 py-5 sm:py-6"><CardHeader className="px-4 sm:px-6"><CardTitle className="flex items-center gap-2 text-base"><Eye className="size-4" />Live draft preview</CardTitle><p className="text-xs text-muted-foreground">Expected from the current editor state · {predicted.length} IDs</p></CardHeader><CardContent className="px-4 sm:px-6"><div className="max-h-56 space-y-2 overflow-auto">{predicted.map(id => <div key={id} className="flex min-w-0 items-center justify-between gap-2 rounded-sm border px-3 py-2 font-mono text-xs"><span className="min-w-0 break-all">{id}</span>{diff.added.includes(id) && <Badge variant="success">+ new</Badge>}</div>)}{!predicted.length && <p className="rounded-sm border border-dashed p-6 text-center text-sm text-muted-foreground">This key would see no models.</p>}</div>{diff.removed.length > 0 && <p className="mt-3 text-xs text-destructive">To remove: {diff.removed.join(", ")}</p>}</CardContent></Card><Card className="gap-5 py-5 sm:py-6"><CardHeader className="px-4 sm:px-6"><CardTitle className="flex items-center gap-2 text-base"><Activity className="size-4" />Last simulated readback</CardTitle><p className="text-xs text-muted-foreground">Independent /v1/models response · {observed.length} IDs</p></CardHeader><CardContent className="px-4 sm:px-6"><div className="mb-4 flex flex-wrap items-center gap-2"><Badge variant={key.readError ? "warning" : "success"}>{key.readError ? "Readback unavailable" : "Readback complete"}</Badge><Button variant="outline" size="sm" onClick={reread}><RotateCcw className="size-3.5" />Read again</Button><Button variant="ghost" size="sm" onClick={downloadJson}><FileJson className="size-3.5" />Export JSON</Button></div>{key.readError && <p className="mb-3 text-xs text-amber-700">Last successful response is retained. Current published result is unverified.</p>}<div className="max-h-44 space-y-2 overflow-auto">{observed.map(id => <div key={id} className="break-all rounded-sm border px-3 py-2 font-mono text-xs">{id}</div>)}{!observed.length && <p className="text-sm text-muted-foreground">No models in the last response.</p>}</div><Button variant="link" size="sm" className="mt-2 px-0" onClick={() => setShowJson(!showJson)}>{showJson ? "Hide" : "Show"} response JSON</Button>{showJson && <pre className="max-h-56 overflow-auto rounded-sm bg-muted p-3 text-[11px]">{JSON.stringify({ object: "list", data: observed.map(id => ({ id, object: "model" })) }, null, 2)}</pre>}</CardContent></Card></div></div></>}
        {page === "qualification" && <Laboratory models={data.models} groups={data.groups} campaigns={data.campaigns} onCampaigns={newCampaigns => setData(old => ({ ...old, campaigns: [...newCampaigns, ...old.campaigns] }))} preferences={preferences} />}
        {page === "settings" && <div className="max-w-2xl space-y-5"><div><h2 className="text-xl font-semibold">Catalogue preferences</h2><p className="mt-1 text-sm text-muted-foreground">Local view defaults for this prototype. Individual list overrides can be reset from their View options menu.</p></div><Card><CardHeader><CardTitle className="text-base">Global defaults</CardTitle></CardHeader><CardContent className="space-y-4"><ViewControls value={preferences} onChange={setPreferences} scope="Global" /><div><p className="mb-2 text-sm font-medium">Primary identity on model cards</p><div className="flex gap-2"><Button variant={preferences.logo === "creator" ? "default" : "outline"} size="sm" onClick={() => setPreferences(old => ({ ...old, logo: "creator" }))}>Creator logo</Button><Button variant={preferences.logo === "provider" ? "default" : "outline"} size="sm" onClick={() => setPreferences(old => ({ ...old, logo: "provider" }))}>Serving providers</Button></div><p className="mt-2 text-xs text-muted-foreground">Choose the primary logo; provider details can be shown separately. Unknown creator brands use text.</p></div></CardContent></Card><Card><CardHeader><CardTitle className="text-base">Prototype UI preference contract</CardTitle></CardHeader><CardContent className="space-y-3"><p className="text-sm text-muted-foreground">The proposed config.json below describes catalogue presentation only. It is not an import-ready plugin config and does not synchronize with Bifrost.</p><pre className="overflow-auto rounded-sm bg-muted p-3 text-xs">{JSON.stringify({ prototype: "bifrost-registry-ui", ui: { viewDefaults: preferences } }, null, 2)}</pre><Button variant="outline" size="sm" onClick={() => { const a = document.createElement("a"); a.href = URL.createObjectURL(new Blob([JSON.stringify({ prototype: "bifrost-registry-ui", ui: { viewDefaults: preferences } }, null, 2)], { type: "application/json" })); a.download = "config.json"; a.click(); URL.revokeObjectURL(a.href); }}>Export proposed config.json</Button></CardContent></Card></div>}
      </main></div></div>
    <Dialog open={discoveryOpen} onOpenChange={setDiscoveryOpen}><DialogContent className="flex max-h-[90vh] max-w-5xl flex-col"><DialogHeader><DialogTitle>Add model from discovery</DialogTitle><DialogDescription>Illustrative catalogue only. Choose a model, review its details and provider access, then save it to this local demo.</DialogDescription></DialogHeader><div className="min-h-0 overflow-auto"><ModelBrowser models={discoveryModels.filter(model => !data.models.some(existing => existing.id === model.id))} onOpen={model => { setCreatingModel(true); setModelError(""); setModelDraft(copy(model)); setDiscoveryOpen(false); }} preferences={preferences} compact label="Discovered models" /></div><DialogFooter><Button variant="outline" onClick={() => { setCreatingModel(true); setModelError(""); setModelDraft(newModel()); setDiscoveryOpen(false); }}>Advanced: custom model</Button><Button variant="ghost" onClick={() => setDiscoveryOpen(false)}>Cancel</Button></DialogFooter></DialogContent></Dialog>
    <Sheet open={!!modelDraft} onOpenChange={open => { if (open || !modelDraft) return; if (!same(modelDraft, creatingModel ? newModel() : data.models.find(m => m.id === modelDraft.id))) setConfirm({ title: "Discard model changes?", text: "Unsaved model details will be lost.", confirmLabel: "Discard changes", cancelLabel: "Keep editing", action: () => setModelDraft(null) }); else setModelDraft(null); }}><SheetContent className="p-4 sm:p-6"><SheetHeader><SheetTitle>{creatingModel ? "Add model" : modelDraft?.name}</SheetTitle><SheetDescription className="sr-only">Edit the model details, provider accesses, and capabilities.</SheetDescription></SheetHeader>{modelDraft && <div className="custom-scrollbar flex-1 space-y-6 overflow-auto pr-2">{creatingModel && <div><label className="mb-2 block text-sm font-medium">Model ID *</label><Input aria-label="Model ID" value={modelDraft.id} onChange={e => setModelDraft({ ...modelDraft, id: e.target.value })} placeholder="model-id" /></div>}<div><label className="mb-2 block text-sm font-medium">Display name *</label><Input aria-label="Display name" value={modelDraft.name} onChange={e => setModelDraft({ ...modelDraft, name: e.target.value })} /></div><div><label className="mb-2 block text-sm font-medium">Creator *</label><Input aria-label="Creator" value={modelDraft.creator} onChange={e => setModelDraft({ ...modelDraft, creator: e.target.value })} placeholder="e.g. OpenAI" /></div><div><label className="mb-2 block text-sm font-medium">Model series *</label><Input aria-label="Model series" value={modelDraft.family} onChange={e => setModelDraft({ ...modelDraft, family: e.target.value })} placeholder="e.g. GPT" /></div><div><label className="mb-2 block text-sm font-medium">Description</label><Textarea aria-label="Description" value={modelDraft.summary} onChange={e => setModelDraft({ ...modelDraft, summary: e.target.value })} /></div><div><label className="mb-2 block text-sm font-medium">Context window</label><Input aria-label="Context window" value={modelDraft.context} onChange={e => setModelDraft({ ...modelDraft, context: e.target.value })} /></div><TaxonomyChoices label="Usage / tasks *" options={tasks} selected={modelDraft.tasks} onChange={tasks => setModelDraft({ ...modelDraft, tasks })} /><TaxonomyChoices label="Input modalities *" options={modalities.filter(m => m !== "Vector")} selected={modelDraft.inputModalities} onChange={inputModalities => setModelDraft({ ...modelDraft, inputModalities })} /><TaxonomyChoices label="Output modalities *" options={modalities} selected={modelDraft.outputModalities} onChange={outputModalities => setModelDraft({ ...modelDraft, outputModalities })} /><section><h3 className="mb-2 text-sm font-semibold">Provider accesses *</h3><div className="space-y-2">{modelDraft.accesses.map((a, i) => <div key={i} className="rounded-sm border p-3"><div className="mb-2 flex items-center justify-between"><span className="text-xs text-muted-foreground">Access {i + 1}</span><Button variant="ghost" size="icon" aria-label={`Remove access ${i + 1}`} disabled={modelDraft.accesses.length === 1} onClick={() => setModelDraft({ ...modelDraft, accesses: modelDraft.accesses.filter((_, j) => i !== j) })}><X className="size-4" /></Button></div><div className="grid gap-2 sm:grid-cols-2"><div><ProviderPicker value={a.provider} onChange={value => setModelDraft({ ...modelDraft, accesses: modelDraft.accesses.map((x, j) => i === j ? { ...x, provider: value } : x) })} />{!["openai", "azure", "anthropic", "bedrock", "google", "moonshot", "openrouter"].includes(a.provider) && <details className="mt-1" open><summary className="text-xs text-muted-foreground">Advanced custom provider</summary><Input aria-label="Custom provider" placeholder="Provider ID" value={a.provider} onChange={e => setModelDraft({ ...modelDraft, accesses: modelDraft.accesses.map((x, j) => i === j ? { ...x, provider: e.target.value } : x) })} /></details>}</div><Input aria-label="Exposed provider ID" placeholder="provider/model" value={a.id} onChange={e => setModelDraft({ ...modelDraft, accesses: modelDraft.accesses.map((x, j) => i === j ? { ...x, id: e.target.value } : x) })} /></div><div className="mt-2 flex items-center justify-between"><span className="text-xs text-muted-foreground">Route: {a.route}</span><UiSelect label="Access status" value={a.status} onChange={value => setModelDraft({ ...modelDraft, accesses: modelDraft.accesses.map((x, j) => i === j ? { ...x, status: value as Access["status"] } : x) })} options={["Configured", "Unknown"]} /></div></div>)}</div><Button variant="outline" size="sm" className="mt-2" onClick={() => setModelDraft({ ...modelDraft, accesses: [...modelDraft.accesses, { provider: "", id: "", route: "Direct provider", status: "Unknown" }] })}><Plus className="size-3.5" />Add access</Button><p className="mt-2 text-xs text-muted-foreground">Short-name routing is configured separately. These rows do not define a load balancer.</p></section><section><h3 className="mb-2 text-sm font-semibold">Capabilities and evidence</h3><div className="space-y-2">{Object.entries(modelDraft.capabilities).map(([name, value]) => <div key={name} className="flex items-center justify-between gap-2 rounded-sm border px-3 py-2"><span className="text-sm">{name}</span><UiSelect label={`${name} evidence`} className="max-w-[230px]" value={value} onChange={value => setModelDraft({ ...modelDraft, capabilities: { ...modelDraft.capabilities, [name]: value as Capability } })} options={["Declared", "Observed in simulated campaign", "Unknown"]} /></div>)}</div><p className="mt-2 text-xs text-muted-foreground">“Observed” here means an illustrative fixture only, never real certification.</p></section>{modelError && <p role="alert" className="rounded-sm border border-destructive/40 bg-destructive/10 p-3 text-sm text-destructive">{modelError}</p>}</div>}<SheetFooter className="flex-row flex-wrap justify-end border-t px-0 pb-0 pt-4">{modelDraft && !creatingModel && <Button variant="ghost" className="mr-auto text-destructive" onClick={() => deleteModel(modelDraft)}>Delete</Button>}<Button variant="outline" onClick={() => setModelDraft(null)}>Cancel</Button><Button onClick={updateModel}>Save model</Button></SheetFooter></SheetContent></Sheet>
    <Sheet open={!!groupDraft} onOpenChange={open => { if (open || !groupDraft) return; const original = data.groups.find(g => g.id === groupDraft.id); if (!same(groupDraft, original || { id: groupDraft.id, name: "", description: "", members: [] })) setConfirm({ title: "Discard group changes?", text: "Unsaved group selections will be lost.", confirmLabel: "Discard changes", cancelLabel: "Keep editing", action: () => setGroupDraft(null) }); else setGroupDraft(null); }}><SheetContent className="p-4 sm:p-6"><SheetHeader><SheetTitle>{groupDraft && data.groups.some(g => g.id === groupDraft.id) ? "Edit group" : "Create group"}</SheetTitle><SheetDescription className="sr-only">Choose the group models and review the impact on virtual keys.</SheetDescription></SheetHeader>{groupDraft && <div className="custom-scrollbar flex-1 space-y-5 overflow-auto pr-2"><div><label className="mb-2 block text-sm font-medium">Name</label><Input aria-label="Group name" value={groupDraft.name} onChange={e => setGroupDraft({ ...groupDraft, name: e.target.value })} /></div><div><label className="mb-2 block text-sm font-medium">Description</label><Input aria-label="Group description" value={groupDraft.description} onChange={e => setGroupDraft({ ...groupDraft, description: e.target.value })} /></div><div><h3 className="mb-2 text-sm font-medium">Models in group</h3><p className="mb-2 text-xs text-muted-foreground">{groupDraft.members.length} selected, including models hidden by filters</p><div className="mb-2 flex gap-1"><Button size="sm" variant={groupEditorView === "cards" ? "secondary" : "ghost"} aria-pressed={groupEditorView === "cards"} onClick={() => setGroupEditorView("cards")}>Cards</Button><Button size="sm" variant={groupEditorView === "tree" ? "secondary" : "ghost"} aria-pressed={groupEditorView === "tree"} onClick={() => setGroupEditorView("tree")}>Creator tree</Button></div>{groupEditorView === "cards" ? <ModelBrowser models={data.models} selected={groupDraft.members} onToggle={id => setGroupDraft(old => old ? { ...old, members: old.members.includes(id) ? old.members.filter(x => x !== id) : [...old.members, id] } : old)} onSetSelected={ids => setGroupDraft(old => old ? { ...old, members: ids } : old)} preferences={preferences} compact label="Group models" /> : <GroupTree models={data.models} selected={groupDraft.members} onToggle={id => setGroupDraft(old => old ? { ...old, members: old.members.includes(id) ? old.members.filter(x => x !== id) : [...old.members, id] } : old)} />}</div><div><h3 className="mb-2 text-sm font-medium">Impact if published</h3>{(() => { const next = data.groups.some(g => g.id === groupDraft.id) ? data.groups.map(g => g.id === groupDraft.id ? groupDraft : g) : [...data.groups, groupDraft]; const affected = keyImpact(data.keys, data.groups, next, data.models); const unaffected = data.keys.filter(k => !affected.some(row => row.key.id === k.id)); const names = (ids: string[]) => ids.map(id => data.models.find(m => m.id === id)?.name || id).join(", ") || "None"; return <div className="space-y-2">{affected.map(({ key: k }) => { const impact = modelImpact(k, data.groups, next); return <div key={k.id} className="rounded-sm border p-3 text-xs"><div className="font-medium text-sm">{k.name} · affected</div><p className="mt-2"><span className="font-medium">Added:</span> {names(impact.added)}</p><p><span className="font-medium">Removed:</span> {names(impact.removed)}</p><p><span className="font-medium">Unchanged:</span> {names(impact.unchanged)}</p><p><span className="font-medium">Local exclusions preserved:</span> {names(impact.exclusions)}</p></div>; })}{unaffected.map(k => <div key={k.id} className="rounded-sm border p-3 text-xs"><span className="font-medium">{k.name} · unaffected</span><p>Visible models: {names(members(k.policy, data.groups))}</p><p>Local exclusions preserved: {names(k.policy.excluded)}</p></div>)}{!data.keys.length && <p className="text-xs text-muted-foreground">No keys exist yet.</p>}</div>; })()}</div></div>}<SheetFooter className="flex-col justify-between border-t px-0 pb-0 pt-4 sm:flex-row">{groupDraft && data.groups.some(g => g.id === groupDraft.id) && <Button variant="ghost" className="text-destructive" onClick={() => { const g = groupDraft; setGroupDraft(null); setConfirm({ title: `Delete ${g.name}?`, text: "Keys using this group will lose its models; their local selections remain.", action: () => { const next = data.groups.filter(x => x.id !== g.id); setData(old => ({ ...old, groups: next, keys: old.keys.map(k => k.policy.groups.includes(g.id) ? { ...k, policy: { ...k.policy, groups: k.policy.groups.filter(id => id !== g.id) }, observed: failRead ? k.observed : exposed({ ...k.policy, groups: k.policy.groups.filter(id => id !== g.id) }, next, old.models), readError: failRead } : k) })); toast.success("Group deleted in demo."); } }); }}>Delete</Button>}<div className="flex flex-wrap gap-2 sm:ml-auto"><Button variant="outline" onClick={() => setGroupDraft(null)}>Cancel</Button><Button onClick={publishGroup}>Publish group</Button></div></SheetFooter></SheetContent></Sheet>
    <Dialog open={!!keyForm} onOpenChange={open => !open && setKeyForm(null)}><DialogContent><DialogHeader><DialogTitle>Create virtual key</DialogTitle><DialogDescription>This prototype creates a simulated key record and no usable credential.</DialogDescription></DialogHeader>{keyForm && <div className="space-y-4"><div><label className="mb-2 block text-sm font-medium">Name</label><Input aria-label="Key name" autoFocus value={keyForm.name} onChange={e => setKeyForm({ ...keyForm, name: e.target.value })} placeholder="e.g. Hermes staging" /></div><div><label className="mb-2 block text-sm font-medium">Client</label><Input aria-label="Client name" value={keyForm.client} onChange={e => setKeyForm({ ...keyForm, client: e.target.value })} placeholder="e.g. Hermes" /></div></div>}<DialogFooter><Button variant="outline" onClick={() => setKeyForm(null)}>Cancel</Button><Button onClick={saveKey}>Create key</Button></DialogFooter></DialogContent></Dialog>
    <Dialog open={!!renameForm} onOpenChange={open => !open && setRenameForm(null)}><DialogContent><DialogHeader><DialogTitle>Rename virtual key</DialogTitle><DialogDescription>Updates the display name in this demo.</DialogDescription></DialogHeader>{renameForm && <div><label className="mb-2 block text-sm font-medium">Name</label><Input aria-label="Key name" autoFocus value={renameForm.name} onChange={e => setRenameForm({ ...renameForm, name: e.target.value })} /></div>}<DialogFooter><Button variant="outline" onClick={() => setRenameForm(null)}>Cancel</Button><Button onClick={() => { if (!renameForm?.name.trim() || data.keys.some(k => k.id !== renameForm.id && k.name.toLowerCase() === renameForm.name.trim().toLowerCase())) { toast.error("Name is empty or already used."); return; } setData(old => ({ ...old, keys: old.keys.map(k => k.id === renameForm.id ? { ...k, name: renameForm.name.trim() } : k) })); setRenameForm(null); toast.success("Key renamed in demo."); }}>Save</Button></DialogFooter></DialogContent></Dialog>
    <Dialog open={!!confirm} onOpenChange={open => !open && setConfirm(null)}><DialogContent><DialogHeader><DialogTitle>{confirm?.title}</DialogTitle><DialogDescription>{confirm?.text}</DialogDescription></DialogHeader><DialogFooter><Button variant="outline" onClick={() => setConfirm(null)}>{confirm?.cancelLabel || "Cancel"}</Button><Button variant="destructive" onClick={() => { confirm?.action(); setConfirm(null); }}>{confirm?.confirmLabel || "Delete"}</Button></DialogFooter></DialogContent></Dialog>
    {tour !== null && <div className="fixed inset-0 z-[70]" aria-live="polite">
      {tourRect ? <div className="pointer-events-none fixed rounded-sm ring-2 ring-primary ring-offset-2" style={{ top: tourRect.top - 5, left: tourRect.left - 5, width: tourRect.width + 10, height: tourRect.height + 10, boxShadow: "0 0 0 9999px rgba(0,0,0,.42)" }} /> : <div className="absolute inset-0 bg-black/40" />}
      <Card role="dialog" aria-modal="true" aria-labelledby="tour-title" onKeyDown={event => { if (event.key === "Escape") setTour(null); }} className="fixed z-[71] w-[min(340px,calc(100vw-32px))] gap-3 border-primary/30 p-4 shadow-lg" style={{ top: tourRect ? tourRect.bottom + 210 < innerHeight ? tourRect.bottom + 14 : Math.max(16, tourRect.top - 205) : 90, left: tourRect ? Math.max(16, Math.min(innerWidth - Math.min(340, innerWidth - 32) - 16, tourRect.left)) : 16 }}>
        <div className="flex items-center justify-between"><Badge variant="secondary">{tour + 1} / {tourSteps.length}</Badge><Button autoFocus variant="ghost" size="icon" aria-label="Skip tour" onClick={() => setTour(null)}><X className="size-4" /></Button></div>
        <h3 id="tour-title" className="text-sm font-semibold">{tourSteps[tour].title}</h3><p className="text-xs text-muted-foreground">{tourSteps[tour].detail}</p>
        <div className="flex justify-between"><Button variant="ghost" size="sm" disabled={tour === 0} onClick={() => setTour(tour - 1)}><ArrowLeft className="size-3.5" />Back</Button><Button size="sm" onClick={() => setTour(tour === tourSteps.length - 1 ? null : tour + 1)}>{tour === tourSteps.length - 1 ? "Finish" : "Next"}<ArrowRight className="size-3.5" /></Button></div>
      </Card>
    </div>}
    <Toaster closeButton position="bottom-right" richColors />
  </SidebarProvider></TooltipProvider>;
}

function Empty({ icon: Icon, title, detail, action }: { icon: typeof Search; title: string; detail: string; action: React.ReactNode }) {
  return <div className="flex min-h-72 flex-col items-center justify-center gap-3 py-12 text-center"><Icon className="size-16 stroke-1 text-muted-foreground" /><h3 className="text-xl font-medium text-muted-foreground">{title}</h3><p className="max-w-lg text-sm text-muted-foreground">{detail}</p><div className="mt-2">{action}</div></div>;
}
